  "evt.religious.ms.budget": "Budget festlegen und gezielt zu sparen beginnen",
  "evt.religious.ms.buyEarly": "Früh einkaufen (die Preise steigen, je näher der Termin rückt)",
  "evt.religious.ms.dday": "Festtag ✨",
  "evt.religious.cheer.early": "Mehrere Monate im Voraus zu sparen ist der beste Schutz gegen die Preisexplosion vor dem Fest – du kaufst, solange es noch ruhig ist.",
  "evt.religious.cheer.onTrack": "Das gezielte Sparen läuft gut: Das Fest wird schön UND schuldenfrei. Genau darum geht es.",
  "evt.religious.cheer.behind": "Die Finanzierung ist im Rückstand: Lieber ein etwas schlichteres Fest als ein Kredit, den man danach abstottert – niemand erinnert sich an den Preis, alle an den Moment.",
  "evt.religious.cheer.lastStretch": "Der große Tag steht kurz bevor: Die letzten Einkäufe auf dem Markt lassen sich morgens besser verhandeln, und eine geschriebene Liste hält Extras draußen.",
  "evt.housewarming.label": "Anderes Ereignis",
